          {selectedBlock.type === 'table' && selectedBlock.table && <section className="inspector-section"><h3>표 설정 <small>{selectedBlock.table.rows.length}행 · {selectedBlock.table.columns.length}열</small></h3><div className="button-row"><button disabled={mode === 'document' && !selectedBlock.table.repeatable} onClick={() => { const t = selectedBlock.table!; patchBlock(selectedBlock.id,{table:{...t,rows:[...t.rows,Object.fromEntries(t.columns.map(c => [c.id,'']))]}}); }}><Plus size={14}/>행 추가</button><button disabled={selectedBlock.table.rows.length <= 1 || (mode === 'document' && !selectedBlock.table.repeatable)} onClick={() => { const t = selectedBlock.table!; patchBlock(selectedBlock.id,{table:{...t,rows:t.rows.slice(0,-1)}}); }}><Minus size={14}/>마지막 행 삭제</button></div><div className="button-row"><button disabled={!structure || selectedBlock.table.columns.length >= 16} onClick={() => { const t=selectedBlock.table!; patchBlock(selectedBlock.id,{table:{...t,columns:[...t.columns,{id:uid(),name:'새 열',width:20,role:'text'}]}}); }}><Plus size={14}/>열 추가</button><button disabled={!structure || selectedBlock.table.columns.length <= 1} onClick={() => { const t=selectedBlock.table!; patchBlock(selectedBlock.id,{table:{...t,columns:t.columns.slice(0,-1)}}); }}><Minus size={14}/>마지막 열 삭제</button></div><p className="panel-hint">표 안의 세로 경계선을 좌우로 드래그하세요.<br/>행 높이는 내용에 따라 자동으로 늘어납니다.</p><details className="column-settings"><summary>열 역할 · 너비 세부 설정</summary>{selectedBlock.table.columns.map(c => <div className="column-setting" key={c.id}><label><span>{c.name}</span><input aria-label={`${c.name} 열 너비`} type="number" min="0.01" max="100" step="0.01" value={Math.round(c.width*100)/100} disabled={!structure} onChange={e => { const t=selectedBlock.table!; const width=clamp(Number(e.target.value),0.01,100); patchBlock(selectedBlock.id,{table:{...t,columns:t.columns.map(x => x.id === c.id ? {...x,width}:x)}}); }}/><small>가중치</small></label><select aria-label={`${c.name} 열 역할`} value={c.role} disabled={!structure} onChange={e => { const t=selectedBlock.table!; patchBlock(selectedBlock.id,{table:{...t,columns:t.columns.map(x => x.id===c.id?{...x,role:e.target.value as typeof c.role}:x)}}); }}><option value="text">일반 텍스트</option><option value="quantity">수량</option><option value="price">단가</option><option value="amount">수량 × 단가</option></select></div>)}</details><Toggle label="합계 표시" disabled={!structure} checked={selectedBlock.table.total} onChange={v => patchBlock(selectedBlock.id,{table:{...selectedBlock.table!,total:v}})}/><Toggle label="문서 작성에서 행 편집 허용" disabled={!structure} checked={selectedBlock.table.repeatable} onChange={v => { if (structure) patchBlock(selectedBlock.id,{table:{...selectedBlock.table!,repeatable:v}}); }}/><p className="panel-hint">표의 열과 본문 격자는 독립적입니다.<br/>머리행은 다음 페이지에도 반복됩니다.</p></section>}
          {selectedBlock.field && <section className="inspector-section"><h3>입력 항목 설정</h3><p className="panel-hint">왼쪽 글자는 항목 이름, 오른쪽은 입력값입니다. 양식 화면에서는 기본값을, 문서 화면에서는 실제 값을 바로 입력합니다.</p><label className="control"><span>항목 이름</span><input value={selectedBlock.field.name} disabled={preview} onChange={e => patchBlock(selectedBlock.id,{field:{...selectedBlock.field!,name:e.target.value}})}/></label><label className="control"><span>자료형</span><select value={selectedBlock.field.type} disabled={!structure} onChange={e => patchBlock(selectedBlock.id,{field:{...selectedBlock.field!,type:e.target.value as 'text'|'number'|'date'|'checkbox',defaultValue:''}})}><option value="text">텍스트</option><option value="number">숫자</option><option value="date">날짜</option><option value="checkbox">체크박스</option></select></label><label className="control"><span>기본값</span><input value={selectedBlock.field.defaultValue} disabled={!structure} placeholder={selectedBlock.field.type === 'checkbox' ? 'true 또는 false' : ''} onChange={e => patchBlock(selectedBlock.id,{field:{...selectedBlock.field!,defaultValue:e.target.value}})}/></label><NumberField label="항목명 폭" disabled={preview} value={selectedBlock.field.labelWidth??0} min={0} max={80} suffix="mm" onChange={v=>{if(!preview)patchBlock(selectedBlock.id,{field:{...selectedBlock.field!,labelWidth:v}});}}/><p className="panel-hint">0은 자동 폭입니다. 이름 칸은 전체의 70%까지, 값 칸은 남은 너비를 사용합니다. 블록 전체 너비는 격자 배치에서 조절하세요.</p><Toggle label="필수 입력" disabled={!structure} checked={selectedBlock.field.required} onChange={v => { if(structure) patchBlock(selectedBlock.id,{field:{...selectedBlock.field!,required:v}}); }}/><p className="field-id">고유 ID · {selectedBlock.field.id}</p></section>}
          {selectedBlock.type === 'image' && <section className="inspector-section"><h3>이미지 설정</h3>{selectedBlock.asset && <div className="inspector-image"><img src={selectedBlock.asset.data} alt={selectedBlock.asset.name}/></div>}<button className="wide-button" disabled={!structure} onClick={() => setAssetTarget(selectedBlock.id)}><ImagePlus size={15}/>이미지 선택 / 교체</button><NumberField label="이미지 높이" disabled={!structure || !!doc.page.widgetGrid} value={doc.page.widgetGrid?Math.round(widgetHeight(doc,selectedBlock.rowSpan??3)/MM):selectedBlock.height} min={5} max={250} suffix="mm" onChange={v => { if(structure) patchBlock(selectedBlock.id,{height:v}); }}/><label className="control"><span>이미지 맞춤 / 자르기</span><select aria-label="이미지 자르기" disabled={!structure} value={selectedBlock.crop?.fit??'contain'} onChange={e=>patchBlock(selectedBlock.id,{crop:{fit:e.target.value as 'contain'|'cover',x:50,y:50}})}><option value="contain">비율 유지 · 전체 표시</option><option value="cover">영역 채우기 · 자르기</option></select></label>{selectedBlock.crop?.fit==='cover'&&<><NumberField label="자르기 가로 위치" disabled={!structure} value={selectedBlock.crop.x} suffix="%" onChange={x=>patchBlock(selectedBlock.id,{crop:{...selectedBlock.crop!,x}})}/><NumberField label="자르기 세로 위치" disabled={!structure} value={selectedBlock.crop.y} suffix="%" onChange={y=>patchBlock(selectedBlock.id,{crop:{...selectedBlock.crop!,y}})}/></>}<p className="panel-hint">이미지 원본 비율은 유지하며 자르기는 표시 영역에만 적용됩니다.</p><button className="danger-button" disabled={!structure || !selectedBlock.asset} onClick={() => deleteBlock(selectedBlock.id)}><Trash2 size={14}/>문서에서 이미지 제거</button></section>}
