          {selectedBlock.type === 'divider' && <section className="inspector-section"><h3>구분선 설정</h3><label className="control"><span>방향</span><select aria-label="구분선 방향" disabled={!structure} value={selectedBlock.direction??'horizontal'} onChange={e=>{const vertical=e.target.value==='vertical';patchBlock(selectedBlock.id,{direction:vertical?'vertical':'horizontal',span:vertical?1:doc.page.columns,col:vertical?Math.min(selectedBlock.col,doc.page.columns-1):0,rowSpan:vertical?4:1,height:vertical?48:selectedBlock.height});}}><option value="horizontal">가로선</option><option value="vertical">세로선</option></select></label><label className="control"><span>선 모양</span><select aria-label="구분선 모양" disabled={!structure} value={selectedBlock.lineStyle??'solid'} onChange={e=>patchBlock(selectedBlock.id,{lineStyle:e.target.value as 'solid'|'dashed'|'dotted'})}><option value="solid">실선</option><option value="dashed">파선 ┄</option><option value="dotted">점선 ···</option></select></label><NumberField label="선 굵기" disabled={!structure} value={selectedBlock.lineWidth} min={.25} max={8} step={.25} suffix="mm" onChange={v=>patchBlock(selectedBlock.id,{lineWidth:v})}/><NumberField label={selectedBlock.direction==='vertical'?'양 끝 여백':'위아래 여백'} disabled={!structure} value={selectedBlock.spacing} max={20} suffix="mm" onChange={v=>patchBlock(selectedBlock.id,{spacing:v})}/><p className="panel-hint">방향을 바꾸면 가로 전체 너비 또는 세로 1열 × 4행으로 설정합니다. 손잡이로 길이와 위치를 조절할 수 있습니다.</p></section>}
